(Module 12 — 6 Pillars + 2 Defense Layers). * * Strategy §12 — provides EVERY class in the security stack as * `@Singleton @Provides` in [SingletonComponent]. There are NO stubs; * every binding here is wired to a REAL Android API implementation. * * ## Interface overrides (Strategy §14.2 Table 10) * * | Brain interface | Real impl (this module) | Replaces | * |-----------------|--------------------------|----------| * | [PermissionChecker] | [RealPermissionChecker] | :feature:system's `providePermissionChecker` (REMOVED) | * | [CredentialVaultInterface] | [CredentialVaultImpl] | Brain's `InMemoryCredentialVault` (REMOVED) | * | [AuditLogPersistence] | [EncryptedAuditLogPersistence] | Brain's `NoOpAuditLogPersistence` (REMOVED) | * * ## Pillar coverage * * - **Pillar 1**: [RealPermissionChecker], [ZeroTrustIntegrityManager], *   [IntegrityTokenVerifier] (default = [NoOpIntegrityTokenVerifier]). * - **Pillar 2**: [KeystoreManager], [PostQuantumBridge], [DynamicRotationManager]. * - **Pillar 3**: [AuthenticationManager], [PinStorage] (default = [SqlCipherPinStorage]). * - **Pillar 4**: [EncryptedStorage], [CredentialVaultImpl], [SqlCipherMigrationManager]. * - **Pillar 5**: [AppLockManager], [FlagSecureManager]. * - **Pillar 6**: [BackupRestoreManager]. * - **Defense Layer 1**: [SupplyChainMonitor]. * - **Defense Layer 2**: [AiAttackDefense]. * - **Audit**: [EncryptedAuditLogPersistence]. * * ## Why everything is `@Singleton` * * All these classes hold state (keystore handles, attempt counters, lock * state). Making them singletons ensures that state is shared across the * app's lifetime — a counter in [AiAttackDefense] must persist across * activities, and the [AppLockManager]'s [kotlinx.coroutines.flow.StateFlow] * must be observable from any screen. * * @see <a href="docs/strategy/NOUS-Strategy-2-14-extracted.txt">§12 Module 12: Security Stack</a> */@Module@InstallIn(SingletonComponent::class)object SecurityModule {    // ─── Pillar 1: Permission & Integrity ────────────────────────────────────    /**     * Real [PermissionChecker] — replaces :feature:system's     * `providePermissionChecker`. Single source of truth for the entire app.     */    @Provides    @Singleton    fun providePermissionChecker(        checker: RealPermissionChecker,    ): PermissionChecker = checker    @Provides    @Singleton    fun provideRealPermissionChecker(        @ApplicationContext context: Context,    ): RealPermissionChecker = RealPermissionChecker(context)    @Provides    @Singleton    fun provideZeroTrustIntegrityManager(        @ApplicationContext context: Context,        supplyChainMonitor: SupplyChainMonitor,    ): ZeroTrustIntegrityManager = ZeroTrustIntegrityManager(context, supplyChainMonitor)    /**     * Default [IntegrityTokenVerifier] — always returns VERIFIED.     *     * The production `:app` module can override this with a real     * `PlayIntegrityTokenVerifier` that hits the Google Play Console endpoint     * for cryptographic JWT verification.     */    @Provides    @Singleton    fun provideIntegrityTokenVerifier(): IntegrityTokenVerifier = NoOpIntegrityTokenVerifier()    // ─── Pillar 2: Keystore & Post-Quantum ───────────────────────────────────    @Provides    @Singleton    fun provideKeystoreManager(        @ApplicationContext context: Context,    ): KeystoreManager = KeystoreManager(context)    @Provides    @Singleton    fun providePostQuantumBridge(        keystoreManager: KeystoreManager,    ): PostQuantumBridge = PostQuantumBridge(keystoreManager)    @Provides    @Singleton    fun provideDynamicRotationManager(        @ApplicationContext context: Context,        keystoreManager: KeystoreManager,    ): DynamicRotationManager = DynamicRotationManager(context, keystoreManager)    // ─── Pillar 3: Multi-Factor Authentication ───────────────────────────────    @Provides    @Singleton    fun provideAuthenticationManager(        @ApplicationContext context: Context,        pinStorage: PinStorage,        aiAttackDefense: AiAttackDefense,        encryptedStorage: EncryptedStorage,    ): AuthenticationManager = AuthenticationManager(context, pinStorage, aiAttackDefense, encryptedStorage)    /**     * Production [PinStorage] — backed by SQLCipher-encrypted Room.     *     * Strategy §12.3 — persists the Argon2id hash to a SQLCipher-encrypted     * Room table (see [SecurityDatabaseProvider]) so the PIN survives     * process death and app restarts. The in-memory impl lives in     * `src/test/kotlin/` for unit tests only.     */    @Provides    @Singleton    fun providePinStorage(impl: SqlCipherPinStorage): PinStorage = impl    @Provides    @Singleton    fun provideSqlCipherPinStorage(dao: PinHashDao): SqlCipherPinStorage =        SqlCipherPinStorage(dao)    @Provides    @Singleton    fun providePinHashDao(provider: SecurityDatabaseProvider): PinHashDao =        provider.pinHashDao()    // ─── Pillar 4: Encrypted Storage & Credential Vault ──────────────────────    @Provides    @Singleton    fun provideEncryptedStorage(        @ApplicationContext context: Context,        keystoreManager: KeystoreManager,    ): EncryptedStorage = EncryptedStorage(context, keystoreManager)    /**     * Real [CredentialVaultInterface] — replaces Brain's     * `InMemoryCredentialVault` (which was lost on process death).     */    @Provides    @Singleton    fun provideCredentialVault(impl: CredentialVaultImpl): CredentialVaultInterface = impl    @Provides    @Singleton    fun provideCredentialVaultImpl(        encryptedStorage: EncryptedStorage,        keystoreManager: KeystoreManager,        appLockManager: AppLockManager,        supplyChainMonitor: SupplyChainMonitor,    ): CredentialVaultImpl = CredentialVaultImpl(        encryptedStorage, keystoreManager, appLockManager, supplyChainMonitor,    )    @Provides    @Singleton    fun provideSqlCipherMigrationManager(        @ApplicationContext context: Context,        keystoreManager: KeystoreManager,    ): SqlCipherMigrationManager = SqlCipherMigrationManager(context, keystoreManager)    // ─── Pillar 5: App Lock & Screen Security ────────────────────────────────    @Provides    @Singleton    fun provideAppLockManager(        authenticationManager: AuthenticationManager,    ): AppLockManager = AppLockManager(authenticationManager)    @Provides    @Singleton    fun provideFlagSecureManager(): FlagSecureManager = FlagSecureManager()    // ─── Pillar 6: Backup & Restore ──────────────────────────────────────────    @Provides    @Singleton    fun provideBackupRestoreManager(        @ApplicationContext context: Context,        encryptedStorage: EncryptedStorage,        credentialVault: CredentialVaultImpl,        appLockManager: AppLockManager,        keystoreManager: KeystoreManager,        supplyChainMonitor: SupplyChainMonitor,    ): BackupRestoreManager = BackupRestoreManager(        context, encryptedStorage, credentialVault, appLockManager, keystoreManager, supplyChainMonitor,    )    // ─── Defense Layer 1: Supply Chain Monitor ───────────────────────────────    @Provides    @Singleton    fun provideSupplyChainMonitor(        @ApplicationContext context: Context,    ): SupplyChainMonitor = SupplyChainMonitor(context)    // ─── Defense Layer 2: AI Attack Defense ──────────────────────────────────    @Provides    @Singleton    fun provideAiAttackDefense(): AiAttackDefense = AiAttackDefense()    // ─── Audit Log Persistence (replaces Brain's NoOpAuditLogPersistence) ────    /**     * Real [AuditLogPersistence] — replaces Brain's `NoOpAuditLogPersistence`.     * Persists brain traces to [EncryptedStorage] (double-layer encrypted).     */    @Provides    @Singleton    fun provideAuditLogPersistence(        impl: EncryptedAuditLogPersistence,    ): AuditLogPersistence = impl    @Provides    @Singleton    fun provideEncryptedAuditLogPersistence(        encryptedStorage: EncryptedStorage,        keystoreManager: KeystoreManager,    ): EncryptedAuditLogPersistence =        EncryptedAuditLogPersistence(encryptedStorage, keystoreManager)}/** * NOUS — Security App Initializers Hilt Module. * * Registers [SecurityInitializer] in the app's `Set<AppInitializer>` * multibinding so [com.roshan.persona.di.AppInitializers] auto-discovers * and runs it on app boot (after [com.roshan.persona.init.DatabaseInitializer] * which is CRITICAL priority). * * Strategy §12.7 — this is the wiring that makes the SupplyChainMonitor * actually run on app start AND every 10 minutes via WorkManager (previously * the monitor existed but was never scheduled). */@Module@InstallIn(SingletonComponent::class)abstract class SecurityInitializersModule {    @Binds    @IntoSet    abstract fun bindSecurityInitializer(impl: SecurityInitializer): AppInitializer}